func TestSearchCache(t *testing.T) {
	body := "body"
	empty := ""

	var tests = []struct {
		name        string
		wpVulnCache map[string]*string
		value       string
		ok          bool
	}{
		{
			name: "akismet",
			wpVulnCache: map[string]*string{
				"akismet": &body,
			},
			value: "body",
			ok:    true,
		},
		{
			name: "akismet",
			wpVulnCache: map[string]*string{
				"BackWPup": &body,
				"akismet":  &body,
			},
			value: "body",
			ok:    true,
		},
		{
			name: "akismet",
			wpVulnCache: map[string]*string{
				"BackWPup": &body,
			},
			value: "",
			ok:    false,
		},
		{
			name: "akismet",
			wpVulnCache: map[string]*string{
				"akismet": nil,
			},
			value: "",
			ok:    false,
		},
		{
			name: "akismet",
			wpVulnCache: map[string]*string{
				"akismet": &empty,
			},
			value: "",
			ok:    true,
		},
		{
			name:        "akismet",
			wpVulnCache: nil,
			value:       "",
			ok:          false,
		},
	}

	for i, tt := range tests {
		value, ok := searchCache(tt.name, tt.wpVulnCache)
		if value != tt.value || ok != tt.ok {
			t.Errorf("[%d] searchCache = (%q, %t), want (%q, %t)", i, value, ok, tt.value, tt.ok)
		}
	}
}

